document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("plaster-form"),t=document.getElementById("plaster-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("plaster-area").value),s=parseFloat(document.getElementById("plaster-thickness").value);if(n<=0||s<=0)return t.textContent="Please enter wall area and plaster thickness.",void 0;const a=n*s/12,r=a/27,o=Math.ceil(a/4),i=Math.ceil(a/2);let l="",c=0;s<=.125?(l="Finish coat",c=Math.ceil(n/100)):s<=.25?(l="Finish coat",c=Math.ceil(n/80)):(l="Base coat",c=Math.ceil(n/40)),t.innerHTML=`\n        <div class="result-section">\n          <h4>Plaster Material Needed:</h4>\n          <p><strong>${a.toFixed(2)} cubic feet</strong></p>\n          <p><strong>${r.toFixed(3)} cubic yards</strong></p>\n          <p>Coverage: ${n} sq ft at ${s}" thick</p>\n        </div>\n        <div class="result-bags">\n          <h4>Bag Estimates:</h4>\n          <p><strong>50lb bags:</strong> ${o} bags (standard calculation)</p>\n          <p><strong>25lb bags:</strong> ${i} bags</p>\n          <p><strong>By coverage method:</strong> ${c} bags (50lb)</p>\n          <p>Coat type: ${l}</p>\n        </div>\n        <div class="result-tips">\n          <p><em>🔧 Always order 10-15% extra for waste and touch-ups</em></p>\n          <p><em>⏱️ Apply in thin, multiple coats for best results</em></p>\n          <p><em>💧 Keep surface moist during curing for maximum strength</em></p>\n        </div>\n      `})});